$contact_phone_tel = '+33609285536';
$contact_email     = 'jmmeuret@outlook.com';
$current_year      = date('Y');
$page_title = $L === 'fr'
  ? 'Chauffeur Privé Côte d\'Azur — Cannes, Monaco & Nice | TSPDV'
  : 'Private Chauffeur French Riviera — Cannes, Monaco & Nice | TSPDV';
$page_desc = $L === 'fr'
  ? "Maison de chauffeur privé sur la Côte d\'Azur. Transferts aéroport, VVIP, aviation d\'affaires FBO, service superyacht. Menton à Saint-Tropez. TSPDV."
  : "Private chauffeur house on the Côte d\'Azur. Airport transfers, VVIP protocol, FBO, superyacht service & villa transfers. Menton to Saint-Tropez. TSPDV.";

$EMBEDDED = [
    'exterior' => ['mime' => 'image/jpeg', 'data' => ''],
    'cabin'    => ['mime' => 'image/jpeg', 'data' => ''],
    'seats'    => ['mime' => 'image/jpeg', 'data' => ''],
];
$BROCHURE_PDF_B64 = '';

// ===== Asset endpoint =====
if (isset($_GET['asset']) && isset($EMBEDDED[$_GET['asset']])) {
    $a = $EMBEDDED[$_GET['asset']];
    header('Content-Type: ' . $a['mime']);
    header('Cache-Control: public, max-age=31536000, immutable');
    header('Content-Disposition: inline');
    echo base64_decode($a['data']);
    exit;
}

// ===== PDF download endpoint =====
if (isset($_GET['download']) && $_GET['download'] === 'brochure') {
    header('Content-Type: application/pdf');
    header('Content-Disposition: attachment; filename="TSPDV_Brochure.pdf"');
    header('Cache-Control: public, max-age=31536000');
    echo base64_decode($BROCHURE_PDF_B64);
    exit;
}

